cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_SIZE
#define TILE_SIZE 32
#endif

// Kernel: C = A * B  (all matrices are N x N, row‑major, half precision)
__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int N) {
    // Shared memory tiles
    __shared__ __half As[TILE_SIZE][TILE_SIZE];
    __shared__ __half Bs[TILE_SIZE][TILE_SIZE];

    // Thread row & column within the output matrix
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float acc = 0.0f;  // accumulate in fp32 for accuracy

    // Loop over tiles of the K dimension
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load A tile (if within bounds)
        int a_row = row;
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (a_row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // Load B tile (if within bounds)
        int b_row = t * TILE_SIZE + threadIdx.y;
        int b_col = col;
        if (b_row < N && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// Wrapper exposed to Python
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Inputs must be half precision");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Inputs must be CUDA tensors");
    TORCH_CHECK(A.sizes() == B.sizes(),
                "Input shapes must match");
    TORCH_CHECK(A.dim() == 2, "Inputs must be 2‑D matrices");
    int64_t N = A.size(0);
    TORCH_CHECK(A.size(1) == N && B.size(0) == N && B.size(1) == N,
                "Inputs must be square matrices");

    auto C = torch::empty_like(A);

    const dim3 block(TILE_SIZE, TILE_SIZE);
    const dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE,
                    (N + TILE_SIZE - 1) / TILE_SIZE);

    // Get raw pointers
    const __half* A_ptr = reinterpret_cast<const __half*>(A.data_ptr<at::Half>());
    const __half* B_ptr = reinterpret_cast<const __half*>(B.data_ptr<at::Half>());
    __half* C_ptr = reinterpret_cast<__half*>(C.data_ptr<at::Half>());

    // Launch on current stream
    auto stream = at::cuda::getCurrentCUDAStream();
    matmul_fp16_kernel<<<grid, block, 0, stream>>>(A_ptr, B_ptr, C_ptr, static_cast<int>(N));

    // Ensure kernel launch succeeded
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel failed: ", cudaGetErrorString(err));
    }

    return C;
}

// Bindings
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision matrix multiplication (CUDA)");
}
'''

# ---------- Compile the extension ----------
matmul_ext = load_inline(name='matmul_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['matmul_fp16'],
                         verbose=False)

# ---------- Python wrapper ----------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that uses a custom CUDA kernel
    for half‑precision matrix multiplication.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are half‑precision, contiguous, on CUDA
        if A.dtype != torch.float16:
            A = A.half()
        if B.dtype != torch.float16:
            B = B.half()
        A = A.contiguous()
        B = B.contiguous()
        return matmul_ext.matmul_fp16(A, B)

# ---------- Helper functions (same API as reference) ----------
def get_inputs():
    N = 2048 * 2
    A = torch.rand(N, N, dtype=torch.float16, device='cuda')
    B = torch.rand(N, N, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special initialization inputs needed
